       var logPath = Path.Combine(outputDirectory, $"monodreams_{timestamp}.log");
       _writer = new StreamWriter(logPath, append: false) { AutoFlush = true };
       ...
       Console.WriteLine(line);
       _writer?.WriteLine(line);  // Dual output: console + file
