1	using System;
2	using System.Collections.Generic;
3	using System.IO;
4	using System.Threading.Tasks;
5	using DefaultEcs.System;
6	using Microsoft.Xna.Framework;
7	using Microsoft.Xna.Framework.Graphics;
8	using MonoDreams.State;
9	
10	namespace MonoDreams.System.Debug;
11	
12	public sealed class ScreenshotCaptureSystem : ISystem<GameState>, IDisposable
13	{
14	    private readonly GraphicsDevice _graphicsDevice;
15	    private readonly float _captureIntervalSeconds;
16	    private readonly string _outputDirectory;
17	
18	    private float _timeSinceLastCapture;
19	    private int _counter;
20	    private bool _pendingSave;
21	    private Color[] _pixelBuffer;
22	    private Texture2D _stagingTexture;
23	
24	    public bool IsEnabled { get; set; }
25	
26	    public ScreenshotCaptureSystem(GraphicsDevice graphicsDevice, float captureIntervalSeconds, string outputDirectory)
27	    {
28	        _graphicsDevice = graphicsDevice;
29	        _captureIntervalSeconds = captureIntervalSeconds;
30	        _outputDirectory = outputDirectory;
31	
32	        Directory.CreateDirectory(outputDirectory);
33	        Logger.Info($"ScreenshotCaptureSystem initialized. Interval: {captureIntervalSeconds}s, output: {outputDirectory}");
34	    }
35	
36	    public void Update(GameState state)
37	    {
38	        if (!IsEnabled) return;
39	
40	        _timeSinceLastCapture += state.Time;
41	
42	        if (_timeSinceLastCapture < _captureIntervalSeconds) return;
43	        if (_pendingSave) return;
44	
45	        _timeSinceLastCapture = 0f;
46	
47	        var frame = Grab();
48	
49	        var filename = MakeFilename(state.TotalTime);
50	        var filePath = Path.Combine(_outputDirectory, filename);
51	
52	        _pendingSave = true;
53	        Task.Run(() =>
54	        {
55	            try
56	            {
57	                File.WriteAllBytes(filePath, frame.png);
58	                Logger.Debug($"Screenshot saved: {filename} (nonBlank={frame.nonBlank}, distinctColors={frame.distinct})");
59	            }
60	            catch (Exception ex)
61	            {
62	                Logger.Error($"Failed to save screenshot: {ex.Message}");
63	            }
64	            finally
65	            {
66	                _pendingSave = false;
67	            }
68	        });
69	    }
70	
71	    /// <summary>
72	    /// Synchronously captures the current backbuffer to a PNG in the output directory
73	    /// and returns whether the frame is non-blank (contains more than one distinct
74	    /// colour). Unlike <see cref="Update"/>, the file is fully written before this
75	    /// method returns, so a headless run can capture a verifiable frame on a chosen
76	    /// game frame and exit immediately afterwards without dropping the save.
77	    /// </summary>
78	    public bool CaptureNow(float gameTime)
79	    {
80	        var frame = Grab();
81	        var filename = MakeFilename(gameTime);
82	        var filePath = Path.Combine(_outputDirectory, filename);
83	
84	        try
85	        {
86	            File.WriteAllBytes(filePath, frame.png);
87	            Logger.Info($"Screenshot saved: {filename} (nonBlank={frame.nonBlank}, distinctColors={frame.distinct})");
88	        }
89	        catch (Exception ex)
90	        {
91	            Logger.Error($"Failed to save screenshot: {ex.Message}");
92	            return false;
93	        }
94	
95	        return frame.nonBlank;
96	    }
97	
98	    private string MakeFilename(float gameTime)
99	    {
100	        var counter = _counter++;
101	        var timestamp = DateTime.Now.ToString("yyyyMMdd_HHmmss_fff");
102	        return $"screenshot_{counter:D6}_gt{gameTime:F2}_{timestamp}.png";
103	    }
104	
105	    /// <summary>
106	    /// Reads the backbuffer, encodes it to PNG, and computes a cheap blank/non-blank
107	    /// metric. Must run on the main thread after <c>FinalDrawSystem</c> has composited
108	    /// the frame (GetBackBufferData + SaveAsPng both need the graphics context).
109	    /// </summary>
110	    private (byte[] png, bool nonBlank, int distinct) Grab()
111	    {
112	        var pp = _graphicsDevice.PresentationParameters;
113	        int width = pp.BackBufferWidth;
114	        int height = pp.BackBufferHeight;
115	
116	        // Lazily allocate or resize buffers
117	        if (_pixelBuffer == null || _pixelBuffer.Length != width * height)
118	        {
119	            _pixelBuffer = new Color[width * height];
120	            _stagingTexture?.Dispose();
121	            _stagingTexture = new Texture2D(_graphicsDevice, width, height);
122	        }
123	
124	        _graphicsDevice.GetBackBufferData(_pixelBuffer);
125	        _stagingTexture.SetData(_pixelBuffer);
126	
127	        // Cheap blank detection: a frame is non-blank if any pixel differs from the
128	        // first one. We also count distinct colours (capped) so the headless log
129	        // carries a coarse "how much was drawn" signal that a test can assert on.
130	        var nonBlank = false;
131	        var first = _pixelBuffer[0];
132	        var distinct = new HashSet<uint>();
133	        foreach (var c in _pixelBuffer)
134	        {
135	            if (c != first) nonBlank = true;
136	            if (distinct.Count < 256) distinct.Add(c.PackedValue);
137	        }
138	
139	        var pngData = new MemoryStream();
140	        _stagingTexture.SaveAsPng(pngData, width, height);
141	        var pngBytes = pngData.ToArray();
142	        pngData.Dispose();
143	
144	        return (pngBytes, nonBlank, distinct.Count);
145	    }
146	
147	    public void Dispose()
148	    {
149	        _stagingTexture?.Dispose();
150	        GC.SuppressFinalize(this);
151	    }
152	}
