137	        {
138	            ["Up"] = InputState.Up, ["Down"] = InputState.Down,
139	            ["Left"] = InputState.Left, ["Right"] = InputState.Right,
140	            ["Jump"] = InputState.Jump, ["Grab"] = InputState.Grab,
141	            ["Orb"] = InputState.Orb, ["Exit"] = InputState.Exit,
142	            ["Interact"] = InputState.Interact,
143	        };
144	
145	        var replaySystem = InputReplaySystem.TryLoad(debugDir, actionMap, _game);
146	
147	        ISystem<GameState> inputSystems;
148	        if (replaySystem != null)
149	        {
150	            inputMappingSystem.SkipHardwareRead = true;
151	            inputSystems = new SequentialSystem<GameState>(
152	                new CursorInputSystem(_world), replaySystem, inputMappingSystem);
153	        }
154	        else
155	        {
156	            inputSystems = new ParallelSystem<GameState>(_parallelRunner,
157	                new CursorInputSystem(_world), inputMappingSystem);
158	        }
159	        
160	        var promptFont = _content.Load<BitmapFont>("Fonts/PPMondwest-Regular-fnt");
161	
162	        var blenderParser = new BlenderLevelParserSystem(_world, _content, _camera);
163	        blenderParser.SetDrawLayerMap(_layers);
164	        blenderParser.RegisterCollectionHandler("Player", (entity, blenderObj) =>
165	        {
166	            var isChild = !string.IsNullOrEmpty(blenderObj.Parent);
167	
168	            if (!isChild)
169	            {
170	                entity.Set(new PlayerState());
171	                entity.Set(new StopMotionEffect { OffsetRadians = MathHelper.ToRadians(2f) });
172	            }
173	            else
174	            {
175	                // Child entities (silhouettes) get visual effects only
176	                var isSilhouette = blenderObj.Name.EndsWith("shilhouette");
177	                var offset = isSilhouette
178	                    ? MathHelper.ToRadians(-4f)
179	                    : MathHelper.ToRadians(2f);
180	                entity.Set(new StopMotionEffect { OffsetRadians = offset });
181	
182	                if (isSilhouette)
183	                {
184	                    ref var sprite = ref entity.Get<SpriteInfoComponent>();
185	                    sprite.YSortDepthBias = -0.0005f;
186	                }
187	            }
188	        });
189	        blenderParser.RegisterCollectionHandler("NPC", (entity, blenderObj) =>
190	        {
191	            var npcName = blenderObj.Name;
192	            entity.Set(new EntityInfoComponent("NPC", npcName));
193	
194	            // EMPTY objects (parent empties in hierarchy) don't have sprites — skip visual setup
195	            if (!entity.Has<SpriteInfoComponent>()) return;
196	
197	            var isSilhouette = blenderObj.Name.EndsWith("shilhouette");
198	
199	            // Silhouette entities rotate counterclockwise; compensate for parent's +2° with -4° local
200	            var offset = isSilhouette
201	                ? MathHelper.ToRadians(-4f)
202	                : MathHelper.ToRadians(2f);
203	            entity.Set(new StopMotionEffect { OffsetRadians = offset });
204	
205	            // Silhouette renders behind parent: negative bias = lower depth = further back
206	            if (isSilhouette)
207	            {
208	                ref var sprite = ref entity.Get<SpriteInfoComponent>();
209	                sprite.YSortDepthBias = -0.0005f;
210	            }
211	
212	            var npcTransform = entity.Get<TransformComponent>();
213	            var npcSprite = entity.Get<SpriteInfoComponent>();
214	            var npcDimensions = new Vector2(
215	                blenderObj.Dimensions?.X ?? npcSprite.Size.X,
216	                blenderObj.Dimensions?.Y ?? npcSprite.Size.Y);
217	
218	            // Create interaction zone entity (wider than the NPC for approach detection)
219	            var zoneEntity = _world.CreateEntity();
220	            zoneEntity.Set(new EntityInfoComponent("NPCZone"));
221	            zoneEntity.Set(new TransformComponent());
222	            zoneEntity.SetParent(entity);
223	
224	            var zoneWidth = (int)(npcDimensions.X * 2.5f);
225	            var zoneHeight = (int)(npcDimensions.Y * 1.5f);
226	            var zoneBounds = new Rectangle(-zoneWidth / 2, -zoneHeight / 2, zoneWidth, zoneHeight);
227	            zoneEntity.Set(new BoxColliderComponent(zoneBounds, passive: true));
228	            zoneEntity.Set(new DialogueZoneComponent(npcName, oneTimeOnly: false, autoStart: false, npcName: npcName));
229	
230	            // Create floating icon entity (above the NPC sprite)
231	            var iconEntity = _world.CreateEntity();
232	            iconEntity.Set(new EntityInfoComponent("InteractionIcon", $"{npcName}Icon"));
233	
234	            // Compute icon position above NPC visual top
235	            var originOffsetY = blenderObj.OriginOffset?.Y ?? 0.5f;
236	            var visualTop = -npcDimensions.Y * (1 - originOffsetY);
237	            var iconOffset = new Vector2(0, visualTop - 6f);
238	
239	            iconEntity.Set(new TransformComponent(iconOffset));
240	            iconEntity.SetParent(entity);
241	            iconEntity.Set(new DynamicTextComponent
242	            {
243	                Target = RenderTargetID.Main,
244	                Font = promptFont,
245	                TextContent = "E",
246	                Color = Color.White,
247	                Scale = 0.4f,
248	                LayerDepth = _layers.GetDepth(GameDrawLayer.Characters, -0.01f),
249	                IsRevealed = true,
250	                VisibleCharacterCount = 1,
251	                RevealingSpeed = 0,
252	                RevealStartTime = 0
253	            });
254	            iconEntity.Set(new DrawComponent
255	            {
256	                Type = DrawElementType.Text,
257	                Target = RenderTargetID.Main
258	            });
259	            // No VisibleComponent initially — managed by NPCInteractionSystem
260	
261	            zoneEntity.Set(new NPCInteractionIcon { IconEntity = iconEntity });
262	        });
263	
264	        var entitySpawnSystem = new EntitySpawnSystem(_world, _content, _renderTargets);
265	        entitySpawnSystem.RegisterEntityFactory("Tile", new TileEntityFactory(_layers));
266	        entitySpawnSystem.RegisterEntityFactory("Wall", new WallEntityFactory(_content, _layers));
267	        entitySpawnSystem.RegisterEntityFactory("Player", new PlayerEntityFactory(_content, _layers));
268	        entitySpawnSystem.RegisterEntityFactory("Enemy", new NPCEntityFactory(_content, _layers));
269	
270	        var levelLoadSystems = new SequentialSystem<GameState>(
271	            new LevelLoadRequestSystem(_world, _content),
272	            blenderParser,
273	            new LDtkTileParserSystem(_world, _content),
274	            new LDtkEntityParserSystem(_world),
275	            entitySpawnSystem);
276	        
277	        // Collision pipeline must run sequentially (movement → velocity → detect → resolve → commit)
278	        // Individual systems keep their internal _parallelRunner for entity-level parallelism
279	        var logicSystems = new SequentialSystem<GameState>(
280	            new MovementSystem(_world, _parallelRunner),
281	            new OrbSystem(_world),
282	            new StopMotionEffectSystem(_world),
283	            new TransformVelocitySystem(_world, _parallelRunner),
284	            new TransformCollisionDetectionSystem<CollisionMessage>(_world, GameCollisionHelper.Create),
285	            new TransformPhysicalCollisionResolutionSystem(_world),
286	            new TransformCommitSystem(_world, _parallelRunner),
287	            new TextUpdateSystem(_world), // Logic only
288	            new NPCInteractionSystem(_world),
289	            new ZoneDialogueTriggerSystem(_world),
290	            new DialogueSystem(
291	                _world,
292	                _content.Load<Texture2D>("Dialouge UI/dialog box medium"),
293	                _content.Load<BitmapFont>("Fonts/PPMondwest-Regular-fnt"),
294	                _content.Load<Texture2D>("Dialouge UI/dialog box character finished talking click to continue indicator - spritesheet")
295	                    .Crop(new Rectangle(96, 0, 16, 16), _graphicsDevice),
296	                _viewportManager.VirtualWidth,
297	                _viewportManager.VirtualHeight,
298	                _layers.GetDepth(GameDrawLayer.DialogueUI),
299	                InputState.Interact,
300	                InputState.Up,
301	                InputState.Down,
302	                new[]
303	                {
304	                    _content.Load<YarnProgram>("Dialogues/hello_world"),
305	                    _content.Load<YarnProgram>("Dialogues/boldo")
306	                },
307	                nameof(EntityType.Interface))
308	            // ... other game logic systems
309	        );
310	        
311	        // Hierarchy system must run AFTER logic systems modify transforms
312	        // but BEFORE any systems read world transforms (camera, rendering, etc.)
313	        var hierarchySystem = new HierarchySystem(_world);
314	
315	        var cameraFollowSystem = new CameraFollowSystem(_world, _camera);
316	
317	        // Cursor position must update AFTER camera has moved to avoid 1-frame lag
318	        var cursorLateUpdateSystem = new CursorPositionSystem(_world, _camera, _viewportManager);
319	
320	        return new SequentialSystem<GameState>(
321	            // new DebugSystem(_world, _game, _spriteBatch), // If needed
322	            inputSystems,
323	            levelLoadSystems,
324	            logicSystems,
325	            hierarchySystem, // Entity hierarchy + transform dirty flag propagation
326	            cameraFollowSystem,
327	            cursorLateUpdateSystem,          // Cursor position updates after camera
328	            new CursorDrawPrepSystem(_world) // Draw prep after position is finalized
329	        );
330	    }
331	    
332	    private SequentialSystem<GameState> CreateDrawSystem()
333	    {
334	        var pixelPerfectRendering = SettingsManager.Instance.Settings.PixelPerfectRendering;
335	
336	        // Systems that prepare DrawComponent based on state (can often be parallel)
337	        var prepDrawSystems = new SequentialSystem<GameState>( // Or parallel if clearing is handled carefully
338	            // Optional: A system to clear all DrawComponents first?
339	            // new ClearDrawComponentSystem(_world),
340	            new CullingSystem(_world, _camera),
341	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering),
342	            new YSortSystem(_world, _camera, _layers),
343	            new TextPrepSystem(_world, pixelPerfectRendering),
344	            new MeshPrepSystem(_world),
345	            new ColliderDebugSystem(_world),
346	            new SpriteDebugSystem(_world)
347	            // ... other systems preparing DrawElements (UI, particles, etc.)
348	        );
349	
350	        // One render pass per view: the world (Main) through the camera, plus screen-space
351	        // UI and HUD. Compose more instances for minimaps / splitscreen / CCTV / portals.
352	        var mainPass = new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
353	            RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera);
354	        var uiPass = new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
355	            RenderTargetID.UI, _renderTargets[RenderTargetID.UI]);
356	        var hudPass = new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
357	            RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]);
358	
359	        // Final system composites the render targets onto the back buffer.
360	        var finalDrawToScreenSystem = new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, new[]
361	        {
362	            RenderLayer.Main(_renderTargets[RenderTargetID.Main]),
363	            RenderLayer.UI(_renderTargets[RenderTargetID.UI]),
364	            RenderLayer.HUD(_renderTargets[RenderTargetID.HUD]),
365	        });
366	
367	        var debugDir = Environment.GetEnvironmentVariable("MONODREAMS_DEBUG_DIR")
368	            ?? Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "debug");
369	        var replayPlan = InputReplayPlan.TryLoad(debugDir);
370	        var screenshotSystem = new ScreenshotCaptureSystem(_graphicsDevice, captureIntervalSeconds: 2.0f, debugDir)
371	        {
372	            IsEnabled = replayPlan?.Screenshots ?? false
373	        };
374	
375	        return new SequentialSystem<GameState>(
376	            prepDrawSystems,
377	            mainPass,
378	            uiPass,
379	            hudPass,
380	            finalDrawToScreenSystem, // Draw RTs to screen
381	            screenshotSystem
382	        );
383	    }
384	
385	    public void Dispose()
386	    {
387	        UpdateSystem.Dispose();
388	        GC.SuppressFinalize(this);
389	    }
390	}

